-- 供应商模块改造 v2.0「一、城市固定化」- 城市区划码种子（幂等，可重复执行）
-- 民政部行政区划码（省+地级两级；直辖市按省级；含港澳台）
-- 生成脚本: scripts/seed_supplier_city_code.py
-- =============================================================
USE `expert_system`;

SET @has_code := (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA='expert_system' AND TABLE_NAME='supplier_city' AND COLUMN_NAME='code');
SET @sql := IF(@has_code=0,
  'ALTER TABLE `supplier_city` ADD COLUMN `code` VARCHAR(6) DEFAULT NULL COMMENT ''民政部行政区划码（省+地级两级）'' AFTER `name`',
  'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @has_uk := (SELECT COUNT(*) FROM information_schema.STATISTICS
  WHERE TABLE_SCHEMA='expert_system' AND TABLE_NAME='supplier_city' AND INDEX_NAME='uk_city_code');
SET @sql2 := IF(@has_uk=0,
  'ALTER TABLE `supplier_city` ADD UNIQUE KEY `uk_city_code` (`code`)',
  'SELECT 1');
PREPARE stmt2 FROM @sql2; EXECUTE stmt2; DEALLOCATE PREPARE stmt2;

